            return f_values
        if average == "macro":
            try:
                result = math.fsum(f_values) / len(f_values)
            except (OverflowError, ValueError) as exc:
                raise FloatingPointError(
                    "non-finite value encountered during fbeta-score "
                    "computation"
                ) from exc
            return _fbeta_result(result)
